const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

const receivedSignature = headers['x-kredo-signature'] || headers['X-KREDO-Signature'] || '';
const expectedSignature = 'sha256=' + (item.computedSignature || '');

if (!receivedSignature || receivedSignature !== expectedSignature) {
  throw new Error('Signature HMAC invalide (X-KREDO-Signature) — requête rejetée');
}

const required = ['runId', 'workflowId', 'entityType', 'entityId', 'workspaceId', 'userId', 'callbackUrl'];
for (const field of required) {
  if (!body[field]) throw new Error(`Champ requis manquant dans le payload : ${field}`);
}

if (body.entityType !== 'company') {
  throw new Error('intel-031-issues-map requiert entityType="company"');
}

return [{
  json: {
    runId: body.runId,
    workflowId: body.workflowId,
    workspaceId: body.workspaceId,
    userId: body.userId,
    companyId: body.entityId,
    callbackUrl: body.callbackUrl,
  }
}];

const upstream = $('Validate Entity').item.json;
const context = $input.first().json;

// ADR-0012 D-3 — même contrainte que intel-030 : le LLM ne peut émettre que
// 3 des 5 valeurs de provenance (relational/folio_legacy/inferred). Ici, les
// enjeux dérivés de context.sectorContext (pain points/réglementaire mutualisés,
// alimentés par une curation humaine antérieure sur d'autres comptes du même
// secteur) sont tagués 'relational' au même titre que le relationnel KREDO
// direct — ce sont des faits de base de données, pas des déductions LLM.

const SYSTEM_PROMPT = `Tu construis la "Cartographie des enjeux" pour Kredo Digital (ESN premium :
Data/IA, Cloud, Product Management, Cybersécurité) — étape 3 de la chaîne de décision
commerciale (ADR-0012). Tu transformes des faits en enjeux priorisés, PAS en offres à
vendre (ça, c'est l'étape 4) ni en actions (étape 5).

RÈGLES ABSOLUES :
1. Le CONTEXTE ci-dessous (JSON) est ta SEULE source. N'invente aucun enjeu qui ne soit
   pas rattachable à un élément du contexte (contact, signal, pain point sectoriel,
   échéance réglementaire, interaction, diagnostic, ou déduction raisonnable explicite).
2. Chaque enjeu porte une provenance parmi EXACTEMENT ces 3 valeurs :
   - "relational" : dérivé de context.contacts/opportunities/missions/recentInteractions/
     signals OU de context.sectorContext (pain points/échéances réglementaires — ce sont
     des faits de base de données mutualisés, pas des déductions) OU de context.processDiagnostic.
   - "folio_legacy" : dérivé de context.folioAnalysisData (import FOLIO, peu fiable et daté).
   - "inferred" : déduction que tu formules toi-même sans qu'elle soit directement traçable.
   N'utilise JAMAIS "human_verified" ni "engine_researched" — valeurs réservées.
3. evidence_level : "observed" si le fait est explicitement dans le contexte, "inferred"
   si c'est une déduction raisonnable, "weak" si c'est une hypothèse fragile.
4. Les 6 notes (importance/urgency/criticality/business_impact/accessibility/kredo_fit)
   sont des ENTIERS 1 à 5. kredo_fit évalue si un des practices du context.offersCatalog
   pourrait répondre à l'enjeu — 1 = aucun rapport, 5 = adéquation évidente. Ne cite
   AUCUNE offre précise (pas de vente ici, juste l'actionnabilité).
5. contact_ids : uniquement des ids présents dans context.contacts, jamais inventés.
6. Consulte context.existingOpenIssues pour éviter de proposer un enjeu quasi identique
   à un enjeu déjà ouvert (best-effort, pas une garantie absolue).
7. Propose entre 3 et 8 enjeux. Si le contexte est trop pauvre pour un enjeu solide,
   n'en propose pas plutôt que d'inventer.
8. recommended_next_probe : une question concrète à poser en RDV pour valider l'enjeu.

FORMAT DE SORTIE — JSON valide UNIQUEMENT, sans backticks, structure EXACTE :
{
  "schema_version": 1,
  "issues": [
    {
      "title": "...",
      "category": "business|it|data|cloud|cyber|delivery|regulatory|people",
      "problem_statement": "...",
      "evidence_level": "observed|inferred|weak",
      "provenance": "relational|folio_legacy|inferred",
      "source_refs": [ { "table": "...", "id": "..." } ],
      "importance": 1-5, "urgency": 1-5, "criticality": 1-5,
      "business_impact": 1-5, "accessibility": 1-5, "kredo_fit": 1-5,
      "contact_ids": ["..."],
      "recommended_next_probe": "..."
    }
  ]
}`;

const userPrompt = `CONTEXTE (source unique de vérité — JSON) :\n${JSON.stringify(context, null, 2)}`;

return [{
  json: {
    ...upstream,
    context,
    systemPrompt: SYSTEM_PROMPT,
    userPrompt,
  }
}];

