const response = $input.first().json;
const upstream = $('Assemble Prompt').item.json;
const textBlock = (response.content || []).find(b => b.type === 'text');
const content = textBlock && textBlock.text;

if (!content) {
  throw new Error('Le LLM a renvoyé un contenu vide');
}

let parsed;
try {
  const clean = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  throw new Error('Réponse LLM non-JSON : ' + content.slice(0, 200));
}

if (parsed.schema_version !== 1) {
  throw new Error('schema_version doit valoir 1');
}
if (!Array.isArray(parsed.issues)) {
  throw new Error('issues manquant ou invalide');
}

const CATEGORIES = new Set(['business','it','data','cloud','cyber','delivery','regulatory','people']);
const EVIDENCE_LEVELS = new Set(['observed','inferred','weak']);
const ALLOWED_PROVENANCE = new Set(['relational','folio_legacy','inferred']);
const SCORE_FIELDS = ['importance','urgency','criticality','business_impact','accessibility','kredo_fit'];
const contactIds = new Set((upstream.context.contacts || []).map(c => c.id));

for (const issue of parsed.issues) {
  if (!issue.title || typeof issue.title !== 'string') throw new Error('Enjeu sans titre');
  if (!CATEGORIES.has(issue.category)) throw new Error(`Catégorie invalide : "${issue.category}"`);
  if (!issue.problem_statement || typeof issue.problem_statement !== 'string') throw new Error(`problem_statement manquant pour "${issue.title}"`);
  if (!EVIDENCE_LEVELS.has(issue.evidence_level)) throw new Error(`evidence_level invalide pour "${issue.title}" : "${issue.evidence_level}"`);
  if (!ALLOWED_PROVENANCE.has(issue.provenance)) throw new Error(`Provenance non autorisée pour "${issue.title}" : "${issue.provenance}" (autorisé: relational, folio_legacy, inferred)`);
  for (const field of SCORE_FIELDS) {
    const v = issue[field];
    if (!Number.isInteger(v) || v < 1 || v > 5) throw new Error(`${field} invalide pour "${issue.title}" : ${v} (attendu entier 1-5)`);
  }
  if (!Array.isArray(issue.contact_ids)) throw new Error(`contact_ids manquant pour "${issue.title}"`);
  for (const cid of issue.contact_ids) {
    if (!contactIds.has(cid)) throw new Error(`contact_id inconnu pour "${issue.title}" : ${cid}`);
  }
  if (!Array.isArray(issue.source_refs)) issue.source_refs = [];
}

if (parsed.issues.length > 12) {
  throw new Error(`Trop d'enjeux proposés (${parsed.issues.length}, max attendu ~8) — probable sur-génération`);
}

const issuesMap = {
  schema_version: 1,
  issues: parsed.issues,
  generated_at: new Date().toISOString(),
};

return [{
  json: {
    ...upstream,
    issuesMap,
    llmUsage: {
      inputTokens: (response.usage && response.usage.input_tokens) || null,
      outputTokens: (response.usage && response.usage.output_tokens) || null,
      model: response.model || 'claude-sonnet-5',
    },
  }
}];

const data = $input.first().json;
const issues = data.issuesMap.issues;
const qaFlags = [];

qaFlags.push({ check: 'has_issues', passed: issues.length > 0, detail: `${issues.length} enjeu(x)` });

const allWeak = issues.length > 0 && issues.every((i) => i.evidence_level === 'weak');
qaFlags.push({
  check: 'not_all_weak_evidence',
  passed: !allWeak,
  detail: allWeak ? 'tous les enjeux sont evidence_level=weak — contexte probablement trop pauvre' : 'OK',
});

const existingTitles = new Set((data.context.existingOpenIssues || []).map((i) => i.title.toLowerCase().trim()));
const possibleDuplicates = issues.filter((i) => existingTitles.has(i.title.toLowerCase().trim()));
qaFlags.push({
  check: 'no_exact_title_duplicates',
  passed: possibleDuplicates.length === 0,
  detail: possibleDuplicates.length > 0 ? `doublons potentiels : ${possibleDuplicates.map(i => i.title).join(', ')}` : 'OK',
});

const allSameCategory = issues.length > 1 && new Set(issues.map((i) => i.category)).size === 1;
qaFlags.push({
  check: 'category_diversity',
  passed: !allSameCategory,
  detail: allSameCategory ? 'tous les enjeux sur une seule catégorie — possible manque de diversité' : 'OK',
});

return [{ json: { ...data, qaFlags } }];

const data = $input.first().json;
const companyName = (data.context.company && data.context.company.name) || 'Compte';

const sourceRefs = [
  { entityType: 'company', entityId: data.companyId, label: 'Fiche compte' },
];

const callbackBody = {
  runId: data.runId,
  phase: 1,
  resultType: 'account_issues_map',
  status: 'succeeded',
  contentJson: data.issuesMap,
  contentText: [
    `# Cartographie des enjeux — ${companyName}`,
    ...data.issuesMap.issues.map((i) => `- ${i.title} (${i.category}) : ${i.problem_statement}`),
  ].join('\n'),
  title: `Cartographie des enjeux — ${companyName}`,
  modelProvider: 'anthropic',
  modelUsed: (data.llmUsage && data.llmUsage.model) || 'claude-sonnet-5',
  tokensInput: (data.llmUsage && data.llmUsage.inputTokens) || null,
  tokensOutput: (data.llmUsage && data.llmUsage.outputTokens) || null,
  contextSnapshot: data.context,
  sourceRefs,
  qaFlags: data.qaFlags || [],
};

return [{
  json: {
    callbackUrl: data.callbackUrl,
    rawBody: JSON.stringify(callbackBody),
  }
}];

const errItem = $input.first().json;
let runId = null;
let callbackUrl = null;

try {
  const ve = $('Validate Entity').item.json;
  runId = ve.runId || null;
  callbackUrl = ve.callbackUrl || null;
} catch (e) {
  // Validate Entity n'a produit aucune sortie exploitable — notification impossible.
}

let errorMessage = 'Erreur inconnue dans le workflow intel-031-issues-map';
if (errItem && errItem.error) {
  errorMessage = typeof errItem.error === 'string' ? errItem.error : (errItem.error.message || JSON.stringify(errItem.error));
} else if (errItem && errItem.message) {
  errorMessage = errItem.message;
}

const callbackBody = {
  runId,
  phase: 1,
  resultType: 'account_issues_map',
  status: 'failed',
  contentJson: {},
  errorMessage,
};

return [{ json: { callbackUrl, rawBody: JSON.stringify(callbackBody) } }];
